const state={locale:localStorage.getItem("hex-locale")||"vi",bootstrap:null,game:null,snapshot:null,selectedDay:null,selectedAgent:0,plannerMode:"manual",method:"mlns",params:{mlns:{adaptive_commit_tolerance:true,use_lns_dp_proposals:true}},timeLimit:"",agentSelectionTimeLimit:"30",autoRearm:true,session:null,sessionTimer:null,planText:"",roles:[],proposalFingerprint:null,zoom:1,replay:null,replayTimer:null,peerStandings:null,local:{catalog:null,groupId:"",caseId:"",caseData:null,method:"mlns",result:null,running:false,dayIndex:0,step:0,playing:false,timer:null,models:null,modelId:"",prediction:null,view:"actual",predicting:false}};
const resumable=new Set(["paused","failed","interrupted"]);
function canResumeSession(session,status=state.snapshot?.state?.status){if(!session||!resumable.has(session.state)||(session.state!=="paused"&&session.recoverable!==true)||!["selecting_agents","in_progress"].includes(status))return false;const recoveryDay=Number(session.progress?.day??session.last_submission?.day),serverDay=Number(state.snapshot?.state?.day);if(status==="selecting_agents"&&Number.isFinite(recoveryDay))return false;return!Number.isFinite(recoveryDay)||!Number.isFinite(serverDay)||recoveryDay<=serverDay}
let dayMetricTimer=null;
const T=k=>I18N[state.locale]?.[k]??I18N.en[k]??k;

async function api(path,options){const response=await fetch(path,options);let data={};try{data=await response.json()}catch{}if(!response.ok)throw new Error(data.error||`HTTP ${response.status}`);return data}
function toast(message,kind=""){const node=document.createElement("div");node.className=`toast ${kind}`;node.textContent=message;$("#toast-stack").append(node);setTimeout(()=>node.remove(),4200)}
function setConnection(ok,text="API"){const node=$("#connection");node.className=`connection ${ok?"ok":"error"}`;node.querySelector("span").textContent=text}
function post(path,body){return api(path,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)})}
function statusLabel(value){return T(value)||String(value||"").replaceAll("_"," ")}
function zoomIcon(kind){const path=kind==="in"?'<path d="M15.5 14h-.79l-.28-.27C15.41 12.59 16 11.11 16 9.5 16 5.91 13.09 3 9.5 3S3 5.91 3 9.5 5.91 16 9.5 16c1.61 0 3.09-.59 4.23-1.57l.27.28v.79l5 4.99L20.49 19zm-6 0C7.01 14 5 11.99 5 9.5S7.01 5 9.5 5 14 7.01 14 9.5 11.99 14 9.5 14"/><path d="M12 10h-2v2H9v-2H7V9h2V7h1v2h2z"/>':'<path d="M15.5 14h-.79l-.28-.27C15.41 12.59 16 11.11 16 9.5 16 5.91 13.09 3 9.5 3S3 5.91 3 9.5 5.91 16 9.5 16c1.61 0 3.09-.59 4.23-1.57l.27.28v.79l5 4.99L20.49 19zm-6 0C7.01 14 5 11.99 5 9.5S7.01 5 9.5 5 14 7.01 14 9.5 11.99 14 9.5 14M7 9h5v1H7z"/>';return`<svg viewBox="0 0 24 24" aria-hidden="true">${path}</svg>`}
function currentGameId(){const match=location.pathname.match(/^\/competition\/game\/(.+)$/);return match?decodeURIComponent(match[1]):null}
function isLocalRoute(){return location.pathname==="/local"}
function updateNav(){$("#competition-nav")?.classList.toggle("active",!isLocalRoute());$("#local-nav")?.classList.toggle("active",isLocalRoute())}
function ownTeamId(){return String(state.bootstrap?.own_team_id??String(state.snapshot?.game_id||"").split(":").at(-1))}

async function boot(){
 try{state.bootstrap=await api("/api/bootstrap");setConnection(true);state.method=state.bootstrap.policies.includes("mlns")?"mlns":state.bootstrap.policies.includes("alns")?"alns":state.bootstrap.policies[0];state.local.method=state.method;renderLocale();updateNav();const gameId=currentGameId();if(gameId)await loadGame(gameId);else if(isLocalRoute())await loadLocal();else renderHome()}catch(error){setConnection(false,T("apiError"));$("#app").innerHTML=`<div class="empty"><h2>${esc(T("apiError"))}</h2><p>${esc(error.message)}</p></div>`}}
function renderLocale(){$("#locale-button").innerHTML=state.locale==="vi"?"🇻🇳 <span>vi</span>":"🇬🇧 <span>en</span>";document.documentElement.lang=state.locale}
function renderHome(){document.title=`${T("matches")} · HEXUDON`;const games=state.bootstrap.games||[];$("#app").innerHTML=`<div class="page-title-row"><h1>${esc(T("matches"))}</h1></div><section class="game-grid">${games.length?games.map(game=>{const retained=Boolean(game.saved),closed=retained&&["finished","failed","cancelled","interrupted"].includes(game.session_state),score=game.score||{},scoreText=game.score?`${score.distinct_types??0} / ${score.cumulative_daily_types??0} / ${score.total_servings??0}`:"",rank=game.rank?`#${game.rank}/${game.rank_count}`:"";return`<article class="game-card ${game.archived?"archived":""}"><div class="game-card-main"><span class="open-pill ${retained?"saved":""}">${esc(retained?(closed?T(game.session_state):T("saved")):T("open"))}</span><h2>${esc(game.name)}</h2><p><b>${game.width}×${game.height}</b> · ${game.total_days} ${esc(T("days").toLowerCase())}</p><p>${esc(game.question_id)}</p>${retained?`<p class="saved-card-meta">${esc(rank)}${rank&&scoreText?" · ":""}${esc(scoreText)}</p>`:""}</div><div class="game-card-foot"><a class="primary-button wide row center-content" href="/competition/game/${encodeURIComponent(game.question_id)}">▶ ${esc(retained?T("analyze"):T("enter"))}</a></div></article>`}).join(""):`<p>${esc(T("noGames"))}</p>`}</section>`}

async function loadLocal(){
 document.title=`${T("local")} · HEXUDON`;$("#team-badge").textContent="LOCAL";clearInterval(state.local.timer);state.local.playing=false;
 try{
  if(!state.local.catalog)state.local.catalog=await api("/api/local/cases");
  if(!state.local.models){try{state.local.models=(await api("/api/traffic/models")).models||[]}catch{state.local.models=[]}}
  if(state.local.modelId&&!state.local.models.some(m=>m.id===state.local.modelId))state.local.modelId="";
  const groups=state.local.catalog.groups||[];
  if(!groups.length){$("#app").innerHTML=`<div class="empty"><h2>${esc(T("localTests"))}</h2><p>${esc(T("noLocalCases"))}</p></div>`;return}
  if(!groups.some(group=>group.id===state.local.groupId))state.local.groupId=(groups.find(group=>group.tier==="brutal")||groups[0]).id;
  const group=groups.find(row=>row.id===state.local.groupId);
  if(!group.cases.some(row=>row.id===state.local.caseId))state.local.caseId=group.cases[0].id;
  if(state.local.caseData?.id!==state.local.caseId)state.local.caseData=await api(`/api/local/case?case_id=${encodeURIComponent(state.local.caseId)}`);
  renderLocal();
 }catch(error){toast(error.message,"error");$("#app").innerHTML=`<div class="empty"><h2>${esc(T("localTests"))}</h2><p>${esc(error.message)}</p></div>`}
}
function localGroup(){return(state.local.catalog?.groups||[]).find(row=>row.id===state.local.groupId)}
function localCaseMeta(){return localGroup()?.cases.find(row=>row.id===state.local.caseId)||{}}
function parameterControl(field,values,attribute,disabled=false){const value=values[field.key]??field.recommended;if(field.type==="boolean")return`<div class="parameter parameter-boolean"><label><input ${attribute}="${esc(field.key)}" type="checkbox" ${value?"checked":""} ${disabled?"disabled":""}><span>${esc(field.label)}</span></label>${field.help?`<small>${esc(field.help)}</small>`:""}</div>`;return`<div class="parameter"><label>${esc(field.label)}</label><input class="input" ${attribute}="${esc(field.key)}" type="number" value="${esc(value??"")}" ${field.min!==undefined?`min="${field.min}"`:""} ${field.max!==undefined?`max="${field.max}"`:""} step="${field.step??"any"}" ${disabled?"disabled":""}></div>`}
function localParameters(){const defs=state.bootstrap.hyperparameters?.[state.local.method]||[],values=state.params[state.local.method]||{};return defs.map(field=>parameterControl(field,values,"data-local-param")).join("")||`<span class="safety-note">Automatic defaults</span>`}
function localScoreMarkup(){const run=state.local.result?.result;if(!run)return"";const score=run.score||{},max=run.optimum_score||{},pct=run.objective_percentages||{};const metrics=[[T("types"),"distinct_types"],[T("daily"),"cumulative_daily_types"],[T("servings"),"total_servings"]];return`<section class="local-score-grid">${metrics.map(([label,key])=>`<article class="score-card"><span>${esc(label)}</span><strong>${score[key]??0}<small> / ${max[key]??0}</small></strong><div class="score-track"><i style="width:${Math.max(0,Math.min(100,Number(pct[key])||0))}%"></i></div><b>${Number(pct[key]??0).toFixed(1)}%</b></article>`).join("")}<article class="score-card compact"><span>${esc(T("runtime"))}</span><strong>${Number(run.runtime_seconds||0).toFixed(3)}<small>s</small></strong><b>${run.valid_days??0}/${(state.local.caseData?.scenario?.config?.daySteps||[]).length} ${esc(T("validDays").toLowerCase())}</b></article></section>`}
function localTrafficView(){const run=state.local.result?.result,days=run?.replay?.days||[],day=days[state.local.dayIndex];if(!day)return null;const dayNumber=Number(day.day),preds=state.local.prediction?.days||[],pred=preds.find(row=>Number(row.day)===dayNumber)||null,actual=Object.entries(day.road_condition||{}).map(([pos,status])=>({pos:Number(pos),status:Number(status)})),predictView=state.local.view==="predict"&&pred;return{dayNumber,pred,actual,predictView,hasPrediction:Boolean(pred),dayInfo:predictView?{traffics:pred.cells.map(cell=>({pos:cell.pos,status:cell.predicted})),actualTraffics:pred.cells.map(cell=>({pos:cell.pos,status:cell.actual}))}:{traffics:actual}}}
function localFrameView(){const run=state.local.result?.result,days=run?.replay?.days||[],day=days[state.local.dayIndex];if(!day)return null;const team=day.teams?.[0]||{},frames=team.frames||[],max=Math.max(0,frames.length-1),step=Math.min(state.local.step,max),frame=frames[step]||frames[0]||{},color="#1976d2";state.local.step=step;const traffic=localTrafficView();return{day,team,frames,max,step,frame,replayTeams:[{teamId:"local",label:state.local.method,color,agents:(frame.agents||[]).map((agent,index)=>({cell:Number(agent.cell),kind:agent.type==="refuel"||Number(agent.type)===1?1:0,fuel:agent.fuel,trail:replayTrail(frames,index,step)}))}],dayInfo:traffic.dayInfo,traffic}}
function localFrameStatsMarkup(view){const frame=view.frame,collected=(frame.collected||[]).length;return`<span class="chip">${esc(T("types"))}: ${frame.types??0}</span><span class="chip">${esc(T("servings"))}: ${frame.servings??0}</span><span class="chip ${collected?"success":""}">${esc(T("collected"))}: ${collected?`+${collected}`:"—"}</span>${(frame.agents||[]).map((agent,index)=>`<span class="agent-fuel-chip">#${index} ${agent.type==="refuel"||Number(agent.type)===1?esc(T("refuel")):`${esc(T("patrol"))} ⛽${agent.fuel??"—"}`}</span>`).join("")}`}
function localTrafficBarMarkup(view){const models=state.local.models||[];if(!state.local.modelId||!state.local.prediction||!view.traffic){return models.length&&!state.local.modelId?`<div class="local-traffic-bar"><span class="chip">${esc(T("trafficModel"))}: ${esc(T("noModel"))}</span></div>`:""}const traffic=view.traffic,acc=traffic.hasPrediction?Math.round(traffic.pred.accuracy*100):null,toggle=`<div class="view-toggle"><button data-local-view="actual" class="text-button ${state.local.view==="actual"?"active":""}">${esc(T("actualView"))}</button><button data-local-view="predict" class="text-button ${state.local.view==="predict"?"active":""}">${esc(T("predictView"))}</button></div>`,dayStat=acc!=null?`<span class="chip ${acc>=80?"success":acc>=50?"selected":"warning"}">${esc(T("day"))} ${traffic.dayNumber}: ${acc}% (${traffic.pred.matched}/${traffic.pred.road_count})</span>`:`<span class="chip">${esc(T("dayNoPred"))}</span>`,overall=`<span class="chip">${esc(T("modelAccuracy"))}: ${Math.round(state.local.prediction.accuracy*100)}% (${state.local.prediction.matched}/${state.local.prediction.road_count})</span>`;return`<div class="local-traffic-bar">${toggle}${dayStat}${overall}<span class="traffic-hint">${esc(T("modelMissed"))}: ◯</span></div>`}
function localPlaybackMarkup(){const view=localFrameView();if(!view)return"";const days=state.local.result.result.replay.days,frame=view.frame,team=view.team;return`<section class="panel local-playback"><div class="local-playback-head"><div><span class="eyebrow">${esc(state.local.method)}</span><h2>${esc(T("replayTitle"))}</h2></div><div class="day-tabs">${days.map((day,index)=>`<button data-local-day="${index}" class="${index===state.local.dayIndex?"active":""}">${esc(T("day"))} ${Number(day.day)+1}</button>`).join("")}</div></div><div class="replay-controls"><button id="local-first" class="icon-button" title="${esc(T("first"))}">|◀</button><button id="local-play" class="icon-button" title="${esc(T("play"))}">${state.local.playing?"Ⅱ":"▶"}</button><button id="local-last" class="icon-button" title="${esc(T("last"))}">▶|</button><input id="local-range" type="range" min="0" max="${view.max}" value="${view.step}"><b id="local-step-label">${esc(T("steps"))} ${view.step}/${view.max}</b></div><div id="local-frame-stats" class="local-frame-stats">${localFrameStatsMarkup(view)}</div>${localTrafficBarMarkup(view)}<div class="map-toolbar"><button class="icon-button map-icon-button" data-local-zoom="out">${zoomIcon("out")}</button><button class="zoom-label text-button" data-local-zoom="reset">${Math.round(state.zoom*100)}%</button><button class="icon-button map-icon-button" data-local-zoom="in">${zoomIcon("in")}</button></div><div class="map-wrap"><div id="local-map-canvas" class="map-canvas">${renderMap({config:state.local.caseData.scenario.config,day:view.dayInfo,replayTeams:view.replayTeams,highlightCells:frame.collected||[]})}</div></div>${legendMarkup(true)}<details class="local-actions"><summary>${esc(T("actionPlan"))} · ${esc(T("day"))} ${Number(view.day.day)+1}</summary><pre class="raw-json">${esc(JSON.stringify(team.actions,null,2))}</pre></details></section>`}
function renderLocal(){const groups=state.local.catalog?.groups||[],group=localGroup(),cases=group?.cases||[],meta=localCaseMeta(),scenario=state.local.caseData?.scenario,config=scenario?.config||{},design=scenario?.design||meta.design||{};$("#app").innerHTML=`<section class="local-heading"><div><span class="eyebrow">OFFLINE WORKSPACE</span><h1>${esc(T("localTests"))}</h1><p>${esc(T("localHelp"))}</p></div><span class="chip primary">${state.local.catalog?.case_count||0} cases</span></section><section class="panel local-controls"><div class="local-control-grid"><div class="field"><label>${esc(T("testSuite"))}</label><select id="local-group">${groups.map(row=>`<option value="${esc(row.id)}" ${row.id===state.local.groupId?"selected":""}>${esc(row.tier.toUpperCase())} · ${row.cases.length}</option>`).join("")}</select></div><div class="field"><label>${esc(T("testCase"))}</label><select id="local-case">${cases.map(row=>`<option value="${esc(row.id)}" ${row.id===state.local.caseId?"selected":""}>${esc(row.name)} · seed ${esc(row.seed??"—")}</option>`).join("")}</select></div><div class="field"><label>${esc(T("method"))}</label><select id="local-method">${state.bootstrap.policies.map(method=>`<option value="${esc(method)}" ${method===state.local.method?"selected":""}>${esc(method)}</option>`).join("")}</select></div><div class="field"><label>${esc(T("trafficModel"))}</label><select id="local-model" title="${esc(T("trafficModel"))}"><option value="">${esc(T("noModel"))}</option>${(state.local.models||[]).map(m=>`<option value="${esc(m.id)}" ${m.id===state.local.modelId?"selected":""}>${esc(m.id)}${m.validation_accuracy!=null?` · ${Math.round(Number(m.validation_accuracy)*100)}%`:""}</option>`).join("")}</select></div><button id="run-local" class="primary-button local-run-button" ${state.local.running?"disabled":""}>${state.local.running?`<span class="mini-spinner"></span> ${esc(T("runningLocal"))}`:`▶ ${esc(T("runLocal"))}`}</button></div><details class="local-parameters"><summary>Hyperparameters</summary><div class="parameters">${localParameters()}</div></details></section><section class="local-case-summary"><article><span>${esc(T("testCase"))}</span><strong>${esc(state.local.caseId)}</strong></article><article><span>${esc(T("target"))}</span><strong>${esc(scenario?.target||meta.target||"—")}</strong></article><article><span>${esc(T("mapSize"))}</span><strong>${config.map?.width||"—"} × ${config.map?.height||"—"}</strong></article><article><span>${esc(T("days"))}</span><strong>${config.daySteps?.length||"—"}</strong></article><article><span>${esc(T("fuel"))}</span><strong>${config.fuelLimits??design.fuel??"—"}</strong></article><article><span>${esc(T("spots"))}</span><strong>${config.spots?.length||"—"}</strong></article></section>${state.local.running?`<section class="panel local-running"><div class="spinner"></div><h3>${esc(T("runningLocal"))}</h3><p>${esc(state.local.caseId)} · ${esc(state.local.method)}</p></section>`:""}${localScoreMarkup()}${localPlaybackMarkup()}${!state.local.result&&!state.local.running?`<section class="panel map-panel"><div class="map-wrap"><div class="map-canvas">${renderMap({config,day:{traffics:[]},replayTeams:[{teamId:"start",label:"start",color:"#1976d2",agents:(config.agents||[]).map(cell=>({cell,kind:0}))}]})}</div></div>${legendMarkup()}</section>`:""}`;bindLocal()}
function collectLocalParams(){const result={};$$('[data-local-param]').forEach(input=>{if(input.type==="checkbox")result[input.dataset.localParam]=input.checked;else if(input.value!=="")result[input.dataset.localParam]=Number(input.value)});return result}
function stopLocalPlayback(){state.local.playing=false;clearInterval(state.local.timer)}
function updateLocalPlayback(){const view=localFrameView();if(!view||!$("#local-range"))return;$("#local-range").value=String(view.step);$("#local-step-label").textContent=`${T("steps")} ${view.step}/${view.max}`;$("#local-play").textContent=state.local.playing?"Ⅱ":"▶";$("#local-frame-stats").innerHTML=localFrameStatsMarkup(view);$("#local-map-canvas").innerHTML=renderMap({config:state.local.caseData.scenario.config,day:view.dayInfo,replayTeams:view.replayTeams,highlightCells:view.frame.collected||[]})}
function bindLocal(){
 $("#local-group")?.addEventListener("change",async event=>{stopLocalPlayback();state.local.groupId=event.target.value;state.local.caseId="";state.local.caseData=null;state.local.result=null;state.local.prediction=null;await loadLocal()});
 $("#local-case")?.addEventListener("change",async event=>{stopLocalPlayback();state.local.caseId=event.target.value;state.local.caseData=null;state.local.result=null;state.local.prediction=null;await loadLocal()});
 $("#local-method")?.addEventListener("change",event=>{state.params[state.local.method]=collectLocalParams();state.local.method=event.target.value;state.local.result=null;state.local.prediction=null;renderLocal()});
 $("#local-model")?.addEventListener("change",event=>{state.local.modelId=event.target.value;state.local.prediction=null;state.local.view="actual";renderLocal()});
 $("#run-local")?.addEventListener("click",runLocal);
 $$('[data-local-view]').forEach(button=>button.addEventListener("click",()=>{state.local.view=button.dataset.localView;renderLocal()}));
 $$('[data-local-day]').forEach(button=>button.addEventListener("click",()=>{stopLocalPlayback();state.local.dayIndex=Number(button.dataset.localDay);state.local.step=0;renderLocal()}));
 $("#local-range")?.addEventListener("input",event=>{stopLocalPlayback();state.local.step=Number(event.target.value);updateLocalPlayback()});
 $("#local-first")?.addEventListener("click",()=>{stopLocalPlayback();state.local.step=0;updateLocalPlayback()});
 $("#local-last")?.addEventListener("click",()=>{stopLocalPlayback();state.local.step=localFrameView()?.max||0;updateLocalPlayback()});
 $("#local-play")?.addEventListener("click",()=>{const view=localFrameView();if(!view)return;if(state.local.step>=view.max)state.local.step=0;state.local.playing=!state.local.playing;clearInterval(state.local.timer);if(state.local.playing)state.local.timer=setInterval(()=>{const current=localFrameView();if(!current||state.local.step>=current.max)stopLocalPlayback();else state.local.step++;updateLocalPlayback()},350);updateLocalPlayback()});
 $$('[data-local-zoom]').forEach(button=>button.addEventListener("click",()=>{state.zoom=button.dataset.localZoom==="in"?Math.min(3,state.zoom*1.25):button.dataset.localZoom==="out"?Math.max(.5,state.zoom/1.25):1;renderLocal()}));
}
async function runLocal(){try{stopLocalPlayback();const params=collectLocalParams();state.params[state.local.method]=params;state.local.running=true;state.local.result=null;state.local.prediction=null;renderLocal();const body={case_id:state.local.caseId,method:state.local.method,hyperparameters:params};if(state.local.modelId)body.traffic_model_id=state.local.modelId;state.local.result=await post("/api/local/run",body);state.local.prediction=state.local.result?.result?.traffic||null;if(state.local.prediction?.error){toast(state.local.prediction.error,"error");state.local.prediction=null}else if(state.local.prediction&&state.local.prediction.road_count>0)state.local.view="predict";state.local.dayIndex=0;state.local.step=0;toast(`${state.local.method}${state.local.modelId?` + ${state.local.modelId}`:""} · ${T("finished")}`,"success")}catch(error){toast(error.message,"error")}finally{state.local.running=false;renderLocal()}}

async function loadGame(gameId,{quiet=false}={}){
 try{if(!quiet)$("#app").innerHTML=`<section class="loading-screen"><div class="spinner"></div><p>${esc(T("loading"))}…</p></section>`;state.snapshot=await api(`/api/games/${encodeURIComponent(gameId)}/snapshot`);state.game=(state.bootstrap.games||[]).find(g=>g.question_id===gameId)||{question_id:gameId,name:"HEXUDON",is_practice:state.snapshot.board?.is_practice,no_reset:state.snapshot.board?.no_reset,total_days:state.snapshot.config?.daySteps?.length};const resettable=state.game.is_practice&&!state.game.no_reset&&!state.game.archived,ranked=!state.game.no_reset&&!state.game.archived;state.peerStandings=ranked?{loading:true}:null;const challenge=competitiveChallenge(),day=Number(challenge?.day?.day??state.snapshot.state?.day);state.selectedDay=Number.isFinite(day)?day:0;document.title=`${state.game.name} · HEXUDON`;$("#team-badge").textContent=`ID:${ownTeamId()||"?"}`;if(state.game.archived&&state.game.saved_session_id)attachSession(await api(`/api/play/sessions/${state.game.saved_session_id}`));else await restoreSession();renderGame();if(ranked)loadStandings()}catch(error){toast(error.message,"error");if(!quiet)$("#app").innerHTML=`<div class="empty"><h2>HEXUDON</h2><p>${esc(error.message)}</p><a href="/" class="secondary-button">${esc(T("back"))}</a></div>`}}
async function loadStandings(){const gameId=state.game?.question_id;if(!gameId)return;try{const data=await api(`/api/games/${encodeURIComponent(gameId)}/standings`);if(state.game?.question_id!==gameId)return;state.peerStandings=data}catch(error){if(state.game?.question_id!==gameId)return;state.peerStandings={error:error.message}}const current=$(".standings");if(current)current.outerHTML=standingsMarkup();const score=scoreSummary(),types=$("#score-types"),daily=$("#score-daily"),servings=$("#score-servings");if(types)types.textContent=`${T("types")}: ${score.types}`;if(daily)daily.textContent=`${T("daily")}: ${score.daily}`;if(servings)servings.textContent=`${T("servings")}: ${score.servings}`}
function attachSession(session){state.session=session;state.plannerMode=session.execution_mode||"manual";if(state.bootstrap.policies.includes(session.method))state.method=session.method;if(session.time_limit_seconds!=null)state.timeLimit=String(session.time_limit_seconds);if(session.agent_selection_time_limit_seconds!=null)state.agentSelectionTimeLimit=String(session.agent_selection_time_limit_seconds);if(typeof session.auto_rearm==="boolean")state.autoRearm=session.auto_rearm;syncProposal();if(state.game?.archived&&session.result)state.snapshot.archived_result=session.result;if(!canResumeSession(session))scheduleSessionPoll()}
async function restoreSession(){try{if(state.session&&state.session.requested_game_id===state.game.question_id&&(!terminal.has(state.session.state)||canResumeSession(state.session))){attachSession(await api(`/api/play/sessions/${state.session.id}`));return}const data=await api("/api/play/sessions"),matches=(data.sessions||[]).filter(s=>s.requested_game_id===state.game.question_id),match=matches.find(s=>!terminal.has(s.state)&&s.state!=="paused")||matches.find(s=>canResumeSession(s));if(match)attachSession(match)}catch{}}

function gameModeLabel(){if(state.game.is_practice&&state.game.no_reset)return T("competitivePractice");if(state.game.is_practice)return T("practice");return T("live")}
function competitiveChallenge(){const raw=state.snapshot?.competitive_state?.prev,day=state.snapshot?.previous_day;if(!raw||!day||!Array.isArray(raw.holder_score))return null;return{raw,day}}
function archivedResult(){return state.game?.archived?state.snapshot.archived_result:null}
function scoreSummary(){const competitive=state.snapshot.competitive_state,timeline=competitive?.standings?.timeline;if(timeline)return{types:timeline.distinct_types??0,daily:timeline.cumulative_daily_types??competitive?.prev?.holder_score?.[1]??0,servings:timeline.total_servings??0,submits:0};const archived=archivedResult()?.detail?.[ownTeamId()];if(archived)return{types:archived.distinct_types??0,daily:archived.cumulative_daily_types??0,servings:archived.total_servings??0,submits:0};const team=state.snapshot.state?.teams?.[ownTeamId()]||{},peerId=String(state.peerStandings?.own_team_id??ownTeamId()),peer=state.peerStandings?.detail?.[peerId]||{};return{types:peer.distinct_types??(team.distinct_types||[]).length,daily:peer.cumulative_daily_types??team.cumulative_daily_types??team.daily_types??0,servings:peer.total_servings??team.total_servings??0,submits:team.submit_count??0}}
function plannerParameters(disabled=false){const defs=(state.bootstrap.hyperparameters?.[state.method]||[]).filter(field=>["commit_tolerance","adaptive_commit_tolerance","use_lns_dp_proposals","use_traffic_gnn"].includes(field.key)),values=state.params[state.method]||{};return defs.map(field=>parameterControl(field,values,"data-param",disabled)).join("")}
function roleEditor(proposal){const count=state.snapshot.config?.agents?.length||0;if(!state.roles.length)state.roles=proposal?.types?.slice()||new Array(count).fill(0);return`<div class="notice">ⓘ <span>${esc(T("agentHint"))}</span></div><div class="role-list">${state.roles.map((kind,index)=>`<div class="role-row"><span>${esc(T("day").replace("Ngày","Xe").replace("Day","Agent"))} ${index} — #${state.snapshot.config.agents[index]}</span><div class="toggle-group"><button data-role-index="${index}" data-role="0" class="${kind===0?"active":""}">${esc(T("patrol"))} (0)</button><button data-role-index="${index}" data-role="1" class="${kind===1?"active":""}">${esc(T("refuel"))} (1)</button></div></div>`).join("")}</div>`}
